package fleet

import (
	"bytes"
	"encoding/json"
	"errors"
	"net/http"
	"strings"
)

// --- configuration delivery -------------------------------------------------

// configPublishRequest is the raw publish envelope. Config is decoded a second
// time as a generic JSON value so a non-object body is rejected even though the
// bytes themselves are valid JSON.
type configPublishRequest struct {
	RequestID   string          `json:"requestId"`
	BaseVersion *int64          `json:"baseVersion"`
	Config      json.RawMessage `json:"config"`
}

// configReceiptRequest is the device application receipt envelope.
type configReceiptRequest struct {
	ReceiptID string `json:"receiptId"`
	Version   int64  `json:"version"`
	Success   *bool  `json:"success"`
	Reason    string `json:"reason"`
}

func (h *handler) publishConfig(w http.ResponseWriter, r *http.Request) {
	var request configPublishRequest
	if err := decodeSingleJSON(r, &request); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
		return
	}
	requestID := strings.TrimSpace(request.RequestID)
	if requestID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "requestId is required"})
		return
	}
	if request.BaseVersion == nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "baseVersion is required"})
		return
	}
	if *request.BaseVersion < 0 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "baseVersion must be a non-negative integer"})
		return
	}
	content, ok := nonEmptyJSONObject(w, request.Config)
	if !ok {
		return
	}

	result, repeat, err := h.store.PublishConfig(r.PathValue("id"), requestID, *request.BaseVersion, content)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrConfigConflict) {
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	status := http.StatusCreated
	if repeat {
		status = http.StatusOK
	}
	writeJSON(w, status, result)
}

// pendingConfig serves the simulated device's pull. Only the newest target is
// ever returned; 204 (with empty body) means up to date or never published.
func (h *handler) pendingConfig(w http.ResponseWriter, r *http.Request) {
	view, ok, err := h.store.PendingConfig(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	if !ok {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	writeJSON(w, http.StatusOK, view)
}

func (h *handler) receiveConfigReceipt(w http.ResponseWriter, r *http.Request) {
	var request configReceiptRequest
	if err := decodeSingleJSON(r, &request); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
		return
	}
	receiptID := strings.TrimSpace(request.ReceiptID)
	if receiptID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "receiptId is required"})
		return
	}
	if request.Version < 1 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version must be a positive integer"})
		return
	}
	if request.Success == nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "success is required"})
		return
	}
	reason := strings.TrimSpace(request.Reason)
	if !*request.Success && reason == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "a failed receipt requires a non-blank reason"})
		return
	}

	receipt, repeat, err := h.store.RecordConfigReceipt(r.PathValue("id"), receiptID, request.Version, *request.Success, reason)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrConfigVersionUnknown) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrConfigConflict) {
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	status := http.StatusCreated
	if repeat {
		status = http.StatusOK
	}
	writeJSON(w, status, receipt)
}

func (h *handler) listConfigs(w http.ResponseWriter, r *http.Request) {
	views, err := h.store.ListConfigs(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"configs": views})
}

func (h *handler) listConfigReceipts(w http.ResponseWriter, r *http.Request) {
	receipts, err := h.store.ListConfigReceipts(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"receipts": receipts})
}

func (h *handler) configStatus(w http.ResponseWriter, r *http.Request) {
	status, err := h.store.GetConfigStatus(r.PathValue("id"))
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"targetVersion":  status.TargetVersion,
		"appliedVersion": status.AppliedVersion,
		"failureReason":  status.FailureReason,
	})
}

// nonEmptyJSONObject validates that raw is exactly one non-empty JSON object
// and returns its original bytes (equality is semantic, so whitespace and key
// order do not matter). It writes a 400 itself for every malformed or
// wrong-shaped value.
func nonEmptyJSONObject(w http.ResponseWriter, raw json.RawMessage) (json.RawMessage, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || !isNonEmptyJSONObject(trimmed) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "config must be a non-empty JSON object"})
		return nil, false
	}
	return trimmed, true
}

package fleet

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"time"
)

// Persistent mode stores every acknowledged mutation as one checksummed record
// in an append-only write-ahead log. A record is the commit unit: either the
// whole record is durable (and visible after recovery) or none of it is, so a
// replay batch can never leave half of its samples behind.
//
// Commit protocol per write (WAL frame and commit journal are separate files so
// the commit decision never depends on parsing a possibly torn frame length):
//
//  1. write the frame at the committed offset and fsync the WAL;
//  2. append a fixed-size entry carrying the new committed WAL length to the
//     commit journal and fsync it;
//  3. only then report success.
//
// Recovery reads the committed length T from the journal, verifies that WAL
// bytes [header, T) form an exact chain of valid frames, applies them, and
// treats bytes (T, EOF] as the residue of an unacknowledged write. Damage to
// committed bytes always fails startup instead of being trimmed away.

const (
	walName     = "wal.log"
	commitName  = "commit.log"
	lockName    = "lock"
	walMagic    = "EDGEFLET" // 8 bytes
	headerLen   = 16         // magic(8) + version(4) + flags(4)
	walVersion  = 1
	commitEntry = 12 // [committed WAL length uint64 LE][crc32 LE]

	// maxRecordPayload bounds a single frame; HTTP bodies are capped at 1MiB so
	// this only rejects absurd length fields from damaged files.
	maxRecordPayload = 8 << 20
)

const (
	recInstance byte = 1 + iota
	recRegister
	recTelemetry
	recReplay
	recRule
	recAlertAck
	recConfigPublish
	recConfigReceipt
	recTaskCreate
	recTaskClaim
	recTaskReport
	recTaskTimeout
	recTaskCancel
	recRetention
)

// ErrStorageUnavailable wraps a durable-write failure at runtime. A request
// that fails this way never mutated queryable state.
var ErrStorageUnavailable = errors.New("storage unavailable")

var crcTable = crc32.MakeTable(crc32.Castagnoli)

// walSink is the commit log behind a persistent store.
type walSink interface {
	appendRecord(recType byte, value any) error
}

type walInstance struct {
	InstanceID []byte `json:"instanceId"`
}

type walRegister struct {
	ID           string    `json:"id"`
	Site         string    `json:"site"`
	RegisteredAt time.Time `json:"registeredAt"`
	LastSeenAt   time.Time `json:"lastSeenAt"`
}

type walTelemetry struct {
	DeviceID   string             `json:"deviceId"`
	Sequence   int64              `json:"sequence"`
	ObservedAt time.Time          `json:"observedAt"`
	Values     map[string]float64 `json:"values"`
	// TrimThrough is the cumulative count of oldest events removed by the
	// retention limit once this sample is committed. Absent/zero in records
	// written before retention existed, which never trimmed anything.
	TrimThrough int64 `json:"trimThrough,omitempty"`
	// Alerts and Ended carry the alert changes judged from this sample, in the
	// same commit unit as the sample itself. Absent in records written before
	// alerting existed.
	Alerts []*Alert `json:"alerts,omitempty"`
	Ended  []*Alert `json:"ended,omitempty"`
}

type walSample struct {
	EventID    string             `json:"eventId"`
	ObservedAt time.Time          `json:"observedAt"`
	Values     map[string]float64 `json:"values"`
}

// walReplay is one committed batch. Samples holds the full ordered batch
// (duplicates included) and Receipt the first-acceptance receipt; new events
// and their sequences are derived by zipping the two during recovery. Alerts
// and Ended carry the alert changes judged from the batch's new samples, in
// the same commit unit as the batch itself.
type walReplay struct {
	DeviceID      string             `json:"deviceId"`
	BatchID       string             `json:"batchId"`
	Samples       []walSample        `json:"samples"`
	Receipt       ReplayReceipt      `json:"receipt"`
	TrimThrough   int64              `json:"trimThrough,omitempty"`
	LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
	LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
	Alerts        []*Alert           `json:"alerts,omitempty"`
	Ended         []*Alert           `json:"ended,omitempty"`
}

// walRetention is one committed retention setting. TrimThrough is the
// cumulative number of oldest events that had to be removed to satisfy the
// new limit at commit time; it can only grow.
type walRetention struct {
	DeviceID    string `json:"deviceId"`
	MaxEvents   int64  `json:"maxEvents"`
	TrimThrough int64  `json:"trimThrough,omitempty"`
}

// walRule is one committed rule create or update. Ended holds the alerts the
// update terminated with reason rule_changed, in the same commit unit.
type walRule struct {
	DeviceID string   `json:"deviceId"`
	Rule     Rule     `json:"rule"`
	Ended    []*Alert `json:"ended,omitempty"`
}

// walAlertAck is one committed alert acknowledgment.
type walAlertAck struct {
