78	func (h *handler) telemetry(w http.ResponseWriter, r *http.Request) {
79		raw := map[string]*float64{}
80		if err := decodeJSON(r, &raw); err != nil || len(raw) == 0 {
81			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values are required"})
82			return
83		}
84		values, ok := metricValues(raw)
85		if !ok {
86			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values must be finite"})
87			return
88		}
89		device, err := h.store.RecordTelemetry(r.PathValue("id"), values)
90		if errors.Is(err, ErrDeviceNotFound) {
91			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
92			return
93		}
94		if errors.Is(err, ErrStorageUnavailable) {
95			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
96			return
97		}
98		if err != nil {
99			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
100			return
101		}
102		writeJSON(w, http.StatusAccepted, device)
103	}
