105	type replayRequest struct {
106		BatchID string `json:"batchId"`
107		Samples []struct {
108			EventID    string             `json:"eventId"`
109			ObservedAt string             `json:"observedAt"`
110			Values     map[string]*float64 `json:"values"`
111		} `json:"samples"`
