298	func (h *handler) setRetention(w http.ResponseWriter, r *http.Request) {
299		var request struct {
300			MaxEvents *int64 `json:"maxEvents"`
301		}
302		if err := decodeSingleJSON(r, &request); err != nil || request.MaxEvents == nil {
303			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "maxEvents is required as a single integer"})
304			return
305		}
306		maxEvents := *request.MaxEvents
307		if maxEvents < 0 || maxEvents > maxRetentionEvents {
308			writeJSON(w, http.StatusBadRequest, map[string]string{
309				"error": fmt.Sprintf("maxEvents must be between 0 and %d", maxRetentionEvents),
310			})
311			return
312		}
