410	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
411		var request struct {
412			Metric  *string  `json:"metric"`
413			Trigger *float64 `json:"trigger"`
414			Recover *float64 `json:"recover"`
415			Enabled *bool    `json:"enabled"`
416			Version int64    `json:"version"`
417		}
418		if err := decodeJSON(r, &request); err != nil {
419			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
420			return
421		}
422		if request.Version < 1 {
423			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
424			return
425		}
426		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
427			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
428			return
429		}
430		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
431			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
432			return
433		}
434		if request.Recover != nil && !finiteFloat(*request.Recover) {
435			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
436			return
437		}
438		update := ruleUpdate{}
439		if request.Metric != nil {
440			metric := strings.TrimSpace(*request.Metric)
441			update.Metric = &metric
442		}
443		if request.Trigger != nil {
444			update.Trigger = request.Trigger
445		}
446		if request.Recover != nil {
447			update.Recover = request.Recover
448		}
449		if request.Enabled != nil {
450			update.Enabled = request.Enabled
451		}
452		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
453		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
454			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
455			return
456		}
457		if errors.Is(err, ErrVersionConflict) {
458			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
459			return
460		}
461		if errors.Is(err, ErrInvalidRule) {
462			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
463			return
464		}
465		if errors.Is(err, ErrStorageUnavailable) {
466			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
467			return
468		}
469		if err != nil {
470			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
471			return
472		}
473		writeJSON(w, http.StatusOK, rule)
474	}
