166	func TestConfigConcurrentPublishesOnSameBaseOnlyOneWins(t *testing.T) {
167		h := NewHandler(NewStore())
168		mustRegister(t, h, "gw")
169	
170		const callers = 16
171		var start sync.WaitGroup
172		start.Add(1)
173		var wg sync.WaitGroup
174		codes := make(chan int, callers)
175		for i := 0; i < callers; i++ {
176			wg.Add(1)
177			go func(i int) {
178				defer wg.Done()
179				start.Wait()
180				body := publishBody(fmt.Sprintf("req-%d", i), 0, fmt.Sprintf(`{"i":%d}`, i))
181				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs", body)
182				codes <- r.Code
183			}(i)
184		}
185		start.Done()
186		wg.Wait()
187		close(codes)
188	
189		created, conflicts := 0, 0
190		for code := range codes {
191			switch code {
192			case http.StatusCreated:
193				created++
194			case http.StatusConflict:
195				conflicts++
196			default:
197				t.Fatalf("unexpected status %d", code)
198			}
199		}
200		if created != 1 || conflicts != callers-1 {
201			t.Fatalf("created=%d conflicts=%d, want 1 and %d", created, conflicts, callers-1)
202		}
203		status := getConfigStatus(t, h, "gw")
204		if status.TargetVersion != 1 {
205			t.Fatalf("target = %d, want 1", status.TargetVersion)
206		}
207	}
