209	func TestConfigRequestDedupRetryReturns200FirstResult(t *testing.T) {
210		store, clock := newClockStore()
211		h := NewHandler(store)
212		mustRegister(t, h, "gw")
213		publishConfig(t, h, "gw", publishBody("req-1", 0, `{"b":1,"a":2}`), http.StatusCreated)
214		firstTime := clock.UTC()
215	
216		*clock = clock.Add(time.Hour)
217		// Same requestId, base and content; reordered keys and different whitespace
218		// are still a retry. Returns 200 with the ORIGINAL publish time.
219		retry := publishConfig(t, h, "gw", publishBody("req-1", 0, `{ "a" : 2 , "b" : 1 }`), http.StatusOK)
220		if retry.Version != 1 {
221			t.Fatalf("retry version = %d, want 1 (no new version)", retry.Version)
222		}
223		if !retry.PublishedAt.Equal(firstTime) {
224			t.Fatalf("retry publishedAt = %s, want first time %s", retry.PublishedAt, firstTime)
225		}
226		status := getConfigStatus(t, h, "gw")
227		if status.TargetVersion != 1 {
228			t.Fatalf("target after retry = %d, want 1", status.TargetVersion)
229		}
230	
231		// Same requestId with a different base or content conflicts.
232		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
233			publishBody("req-1", 0, `{"a":2,"b":3}`)); r.Code != http.StatusConflict {
234			t.Fatalf("changed content status = %d, want 409", r.Code)
235		}
236		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
237			publishBody("req-1", 1, `{"a":2,"b":1}`)); r.Code != http.StatusConflict {
238			t.Fatalf("changed base status = %d, want 409", r.Code)
239		}
240		// Numeric equality is by value, and array order is significant.
241		publishConfig(t, h, "gw", publishBody("req-2", 1, `{"n":[1,2]}`), http.StatusCreated)
242		publishConfig(t, h, "gw", publishBody("req-2", 1, `{"n":[1.0,2.0]}`), http.StatusOK)
243		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
244			publishBody("req-2", 1, `{"n":[2,1]}`)); r.Code != http.StatusConflict {
245			t.Fatalf("reordered array status = %d, want 409", r.Code)
246		}
247	}
