321		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
322			publishBody("req-1", 0, `{"v":9007199254740993}`)); r.Code != http.StatusConflict {
323			t.Fatalf("changed old request = %d, want 409", r.Code)
324		}
325		if configs := listConfigs(t, h, "gw"); len(configs) != 2 {
