478		postReceipt(t, h, "gw", receiptBody("rc-ok", 1, true, ""), http.StatusCreated)
479		status = getConfigStatus(t, h, "gw")
480		if status.AppliedVersion != 1 || status.FailureReason != "" {
481			t.Fatalf("status after recovery = %+v", status)
482		}
483	}
